const page = $('取得頁面內 PDF 候選').item.json;
const blocks = $input.first().json.results ?? [];
const isFile = (block) => block.type === 'pdf' || block.type === 'file';
const isEmptyParagraph = (block) => block.type === 'paragraph' && !(block.paragraph?.rich_text ?? []).some(item => (item.plain_text ?? item.text?.content ?? '').trim());
const meaningful = blocks.filter(block => !isEmptyParagraph(block));
const files = meaningful.filter(isFile);
const candidate = files[0];
const fileInfo = candidate?.[candidate?.type];
const source = fileInfo?.file ?? fileInfo?.external;
const title = (page.properties?.Name?.title ?? []).map(item => item.plain_text ?? item.text?.content ?? '').join('').trim() || '派工單';
const safeName = title.replace(/[\\/:*?"<>|]/g, '_');
const isPdf = candidate?.type === 'pdf' || /\.pdf(?:$|[?#])/i.test(source?.url ?? '') || /pdf/i.test(fileInfo?.name ?? '');
return [{ json: {
  page_id: page.id ?? null,
  source_block_id: candidate?.id ?? null,
  pdf_url: source?.url ?? null,
  file_name: /\.pdf$/i.test(fileInfo?.name ?? '') ? fileInfo.name : safeName + '.pdf',
  should_recover: meaningful.length === 1 && files.length === 1 && Boolean(source?.url) && isPdf,
} }];

const source = $('解析 AI 判讀結果1').item.json;
const results = $input.first().json.results ?? [];
const textOf = (block) => {
  const data = block?.[block.type] ?? {};
  const rich = data.rich_text ?? data.text ?? [];
  return Array.isArray(rich) ? rich.map(item => item.plain_text ?? item.text?.content ?? '').join('') : '';
};
const heading = results.find(block => String(textOf(block)).replace(/\s/g, '').replace(/：/g, ':') === '工項:');
const taskBlocks = (Array.isArray(source.tasks) ? source.tasks : [])
  .filter(task => typeof task === 'string' && task.trim())
  .map(task => ({ object: 'block', type: 'to_do', to_do: { rich_text: [{ type: 'text', text: { content: task.trim() } }], checked: false } }));
const text = (content) => ({ type: 'text', text: { content } });
const children = heading
  ? taskBlocks
  : [
      { object: 'block', type: 'heading_2', heading_2: { rich_text: [text('工項：')] } },
      ...taskBlocks,
      { object: 'block', type: 'divider', divider: {} },
      { object: 'block', type: 'heading_2', heading_2: { rich_text: [text('成果回報：')] } },
      { object: 'block', type: 'paragraph', paragraph: { rich_text: [] } },
      { object: 'block', type: 'divider', divider: {} },
      { object: 'block', type: 'heading_2', heading_2: { rich_text: [text('回報文件：')] } },
      { object: 'block', type: 'paragraph', paragraph: { rich_text: [] } },
    ];
const requestBody = heading
  ? { children, position: { type: 'after_block', after_block: { id: heading.id } } }
  : { children };
return [{ json: { page_id: source.page_id, request_body: JSON.stringify(requestBody) } }];

const input = $input.first().json;
const raw = input.text ?? input.response ?? input.output ?? Object.values(input).find((value) => typeof value === 'string' && value.trim().startsWith('{'));

if (!raw) { throw new Error('找不到 Gemini 的 JSON 回傳內容'); }

let extracted;
try { extracted = JSON.parse(String(raw).trim()); }
catch { throw new Error('Gemini 回傳內容不是有效 JSON：' + raw); }

const page = $('取得待辨識派工單1').item.json;

return [{
  json: {
    ...extracted,
    page_id: page.id ?? null,
    raw_ai_response: String(raw).trim(),
  },
}];

// Run Once for All Items. Keep raw Notion blocks (Simplify Output = false).
const blocks = $input.all().map(i => i.json);
const text = cell => (cell || []).map(r => r.plain_text ?? r.text?.content ?? r.mention?.user?.name ?? '').join('').trim();
const norm = s => String(s).replace(/\s+/g, '');
const heading = blocks.find(b => /^heading_[123]$/.test(b.type) && norm(text(b[b.type]?.rich_text ?? b[b.type]?.text)) === '公司所有人聯絡資訊');
if (!heading) throw new Error('找不到「公司所有人聯絡資訊」標題。請確認頁面與讀取權限，且關閉 Simplify Output。');
const siblings = blocks.filter(b => b.parent_id === heading.parent_id);
const after = siblings.slice(siblings.findIndex(b => b.id === heading.id) + 1);
let table;
for (const b of after) {
  if (/^heading_[123]$/.test(b.type)) break;
  if (b.type === 'table') { table = b; break; }
}
if (!table) throw new Error('指定標題下找不到表格；不會改讀其他名單。');
const rows = blocks.filter(b => b.type === 'table_row' && (b.parent_id === table.id || b.parent?.block_id === table.id));
if (!rows.length) throw new Error('表格沒有列。請啟用 Fetch Nested Blocks 與 Return All。');
const headers = rows[0].table_row.cells.map(c => norm(text(c)));
const required = ['人員', 'Notion帳號', '信箱'];
const indices = required.map(h => headers.indexOf(h));
if (indices.some(i => i < 0) || required.some(h => headers.filter(x => x === h).length !== 1)) throw new Error('表格必須各有一個欄位：人員、Notion帳號、信箱。');
const result = [], errors = [], seen = new Set();
for (let n = 1; n < rows.length; n++) {
  const cells = rows[n].table_row.cells;
  if (cells.every(c => !text(c) && !(c || []).some(r => r.mention?.user?.id))) continue;
  const name = text(cells[indices[0]]);
  const account = cells[indices[1]] || [];
  const email = text(cells[indices[2]]);
  const mentions = account.filter(r => r.type === 'mention' && r.mention?.type === 'user');
  const id = mentions[0]?.mention?.user?.id;
  const canonical = text(account).replace(/^@/, '').trim();
  const label = `第 ${n + 1} 列（${name || '未填姓名'}）`;
  if (!name || !email) { errors.push(`${label}：必要欄位空白`); continue; }
  if (mentions.length !== 1 || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id || '')) { errors.push(`${label}：Notion帳號必須包含一個真正的 @使用者提及`); continue; }
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { errors.push(`${label}：信箱格式不正確`); continue; }
  if (seen.has(id.toLowerCase())) { errors.push(`${label}：重複的 Notion user ID`); continue; }
  seen.add(id.toLowerCase());
  result.push({json: {Name: name, canonical_name: canonical, aliases: email, 'Notion user ID': id}});
}
if (errors.length) throw new Error('名單驗證失敗，未輸出或覆寫 CSV：\n' + errors.join('\n'));
if (!result.length) throw new Error('名單沒有有效人員，未輸出或覆寫 CSV。');
return result;

// n8n Code node: run once for all items; the workflow processes one page per iteration.
const source = $('解析 AI 判讀結果1').item.json;
const personnel = $input.first().json;
const today = $now.setZone('Asia/Taipei').toISODate();

function dayNumber(value) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const stamp = Date.parse(value + 'T00:00:00Z');
  if (!Number.isFinite(stamp) || new Date(stamp).toISOString().slice(0, 10) !== value) return null;
  return stamp / 86400000;
}

const confidence = Number(source.confidence);
const passed = confidence >= 80 && personnel.all_matched === true;
let status = '內容待確認';
let daysUntilTask = null;
if (passed) {
  const scheduledDay = dayNumber(source.date_start);
  const currentDay = dayNumber(today);
  // Do not guess a completed/in-progress status for a malformed date.
  // A technical failure stays a failure, rather than changing the existing review rules.
  if (scheduledDay === null || currentDay === null) {
    throw new Error('無法判定任務日期狀態：date_start 必須是有效的 YYYY-MM-DD；尚未寫入頁面。');
  }
  daysUntilTask = scheduledDay - currentDay;
  status = daysUntilTask >= 2 ? 'Not started' : daysUntilTask >= 0 ? 'In progress' : 'Done';
}

const reasons = [];
if (!passed) {
  const explanation = typeof source.review_reason === 'string' ? source.review_reason.trim() : '';
  if (!(confidence >= 80)) {
    reasons.push('Gemini 信心分數未達 80：' + (Number.isFinite(confidence) ? confidence : '未提供有效分數'));
    if (!explanation) reasons.push('Gemini 未提供具體的信心不足原因，請人工檢查原始 PDF。');
  }
  if (explanation) reasons.push('Gemini 判讀原因：' + explanation);
  if (personnel.all_matched !== true) {
    const unmatched = Array.isArray(personnel.unmatched)
      ? personnel.unmatched.map(value => String(value).trim()).filter(Boolean) : [];
    reasons.push(unmatched.length
      ? '人員無法對照：' + [...new Set(unmatched)].join('、')
      : '人員對照未全部通過；對照服務未提供未匹配姓名，請檢查 CSV。');
  }
}

const paragraph = content => ({ object: 'block', type: 'paragraph', paragraph: {
  rich_text: [{ type: 'text', text: { content } }],
} });
const children = [];
if (!passed) {
  children.push({ object: 'block', type: 'divider', divider: {} });
  children.push({ object: 'block', type: 'heading_2', heading_2: {
    rich_text: [{ type: 'text', text: { content: '內容待確認｜自動檢查備註' } }],
  } });
  children.push(paragraph('檢查日期（台灣）：' + today + '；Gemini 信心分數：' +
    (Number.isFinite(confidence) ? confidence + '/100' : '無有效分數')));
  // Keep each text object under Notion's text length limit and requests below 100 children.
  const reasonText = reasons.join('\n');
  const bounded = reasonText.length > 12000
    ? reasonText.slice(0, 12000) + '\n（內容過長，其餘請查看 n8n 執行紀錄。）' : reasonText;
  for (let start = 0; start < bounded.length; start += 1800) {
    children.push(paragraph(bounded.slice(start, start + 1800)));
  }
}

return [{ json: {
  page_id: source.page_id,
  target_status: status,
  needs_review: !passed,
  evaluated_date: today,
  days_until_task: daysUntilTask,
  review_reasons: reasons,
  review_request_body: { children },
}, pairedItem: { item: 0 } }];

const columns = ['Name', 'canonical_name', 'aliases', 'Notion user ID'];
const rows = $input.all();
if (!rows.length) throw new Error('沒有資料，未產生 CSV。');
const quote = value => '"' + String(value ?? '').replace(/"/g, '""') + '"';
const csv = '\uFEFF' + columns.join(',') + '\r\n' + rows.map(i => columns.map(k => quote(i.json[k])).join(',')).join('\r\n') + '\r\n';
const fileName = 'personnel-map.csv';
const data = await this.helpers.prepareBinaryData(Buffer.from(csv, 'utf8'), fileName, 'text/csv');
return [{json: {fileName, rowCount: rows.length, columns}, binary: {data}}];

const source = new Map($('整理 CSV 欄位').all().map(i => [i.json['Notion user ID'].toLowerCase(), i.json]));
const seen = new Set();
const result = $input.all().map(({json:user}) => {
  const id = String(user.id || '').toLowerCase();
  const row = source.get(id);
  const name = String(user.name || '').trim();
  if (!row || seen.has(id)) throw new Error('帳號查詢回傳 ID 不符或重複，停止輸出。');
  if (!name || ['anonymous','untitled','匿名'].includes(name.replace(/^@/,'').toLowerCase())) throw new Error(row.Name + '：User API 未回傳有效名稱，請確認整合使用者讀取權限。');
  seen.add(id);
  return {json:{Name:row.Name,canonical_name:name,aliases:row.aliases,'Notion user ID':row['Notion user ID']}};
});
if (seen.size !== source.size) throw new Error('帳號查詢結果不完整，停止輸出。');
return result;
